/*!
 * Rembric — local HTMX 2.x mirror (placeholder)
 *
 * The real HTMX 2.x file (~50KB minified) is intentionally NOT committed
 * to the repo. Operators with privacy-sensitive deployments can drop a
 * locally-pinned copy into dist/dashboard/public/assets/htmx.min.js at
 * deploy time. The dashboard's HTML forms work fully without HTMX; the
 * library is loaded as a progressive enhancement only.
 *
 * To vendor the real file:
 *   curl -L -o dist/dashboard/public/assets/htmx.min.js \
 *     https://unpkg.com/htmx.org@2.0.4/dist/htmx.min.js
 */
(function () {
  // No-op stub: window.htmx is defined as a no-op so missing real script
  // does not throw on pages that reference it.
  if (typeof window !== 'undefined' && !window.htmx) {
    window.htmx = {
      on: function () {},
      off: function () {},
      trigger: function () {},
      ajax: function () {},
    };
  }
})();
